import json, glob, re
res={}
for rf in glob.glob('task_*.result.json'):
    d=json.load(open(rf)); res[rf.replace('.result.json','')]=d.get('reward')
BG=re.compile(r'nohup\b|&\s*(\$|\n|#|;|\Z)|&\s*echo|systemctl (start|restart)|service\s+\S+\s+start|\./\S+\s*&')
for mf in sorted(glob.glob('task_*.messages.json')):
    tid=mf.replace('.messages.json','')
    msgs=json.load(open(mf))
    seen_selfverify=False
    bg_after=0
    for m in msgs:
        if m.get('role')=='tool' and m.get('name')=='_tb2_self_verify':
            seen_selfverify=True
        if m.get('role')=='assistant':
            for tc in (m.get('tool_calls') or []):
                fn=tc['function']['name']
                if fn=='_tb2_self_verify':
                    seen_selfverify=True
                elif fn=='Bash' and seen_selfverify:
                    try: cmd=json.loads(tc['function']['arguments']).get('command','')
                    except: cmd=''
                    if BG.search(cmd):
                        bg_after+=1
    if seen_selfverify:
        print(res[tid], tid, 'selfverify_fired', 'bg_after_nudge=',bg_after)
"

